package org.springframework.samples.petclinic.repository.springdatajpa;

import java.util.Collection;

import org.springframework.context.annotation.Profile;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.Repository;
import org.springframework.data.repository.query.Param;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Spring Data JPA specialization of the {@link OwnerRepository} interface
 *
 * @author Michael Isvy
 * @since 15.1.2013
 */

@Profile("spring-data-jpa")
public interface SpringDataOwnerRepository extends OwnerRepository, Repository<Owner, Integer> {

    @Override
    @Query("SELECT DISTINCT owner FROM Owner owner left join fetch owner.pets WHERE owner.lastName LIKE :lastName%")
    Collection<Owner> findByLastName(@Param("lastName") String lastName);

    @Override
    @Query(
        value = "SELECT owner FROM Owner owner WHERE owner.lastName LIKE CONCAT(:lastName, '%')",
        countQuery = "SELECT COUNT(owner) FROM Owner owner WHERE owner.lastName LIKE CONCAT(:lastName, '%')")
    Page<Owner> findByLastName(@Param("lastName") String lastName, Pageable pageable);

    @Override
    @Query(
        value = "SELECT owner FROM Owner owner",
        countQuery = "SELECT COUNT(owner) FROM Owner owner")
    Page<Owner> findAll(Pageable pageable);

    @Override
    @Query("SELECT owner FROM Owner owner left join fetch owner.pets WHERE owner.id =:id")
    Owner findById(@Param("id") int id);

    @Override
    @Query("SELECT owner FROM Owner owner WHERE owner.telephone = :telephone")
    Collection<Owner> findByTelephone(@Param("telephone") String telephone);

    @Override
    @Query("SELECT owner FROM Owner owner WHERE LOWER(owner.lastName) = LOWER(:lastName)")
    Collection<Owner> findByLastNameIgnoreCase(@Param("lastName") String lastName);

    @Override
    @Query("SELECT owner FROM Owner owner WHERE LOWER(owner.email) = LOWER(:email)")
    Collection<Owner> findByEmailIgnoreCase(@Param("email") String email);

    @Override
    @Query("SELECT owner FROM Owner owner WHERE owner.customerCode LIKE CONCAT(:prefix, '%')")
    Collection<Owner> findByCustomerCodeStartingWith(@Param("prefix") String prefix);

    @Override
    @Query("SELECT COUNT(owner) FROM Owner owner")
    long count();

    @Override
    @Query("SELECT COUNT(owner) FROM Owner owner WHERE LOWER(owner.city) = LOWER(:city)")
    long countByCity(@Param("city") String city);

    @Override
    @Query("SELECT COUNT(owner) FROM Owner owner WHERE owner.registrationDate = :registrationDate")
    long countByRegistrationDate(@Param("registrationDate") java.time.LocalDate registrationDate);
}

